def trade_guide_dict(t):
    tr = t["trade"]
    return dict(slug=f"google-for-{t['slug']}",
      title=f"Google for {tr}: more calls, less wasted spend",
      desc=f"A practical Google guide for {tr}: stop wasting Google Ads money, set up your Google Business Profile, collect reviews and fix your website.",
      h1=f"Google for {tr}: more calls, less wasted spend",
      lede=f"Four things that make a difference for {t['who']}, and what you can check today. The example searches are illustrative; real search terms differ by area and business.",
      sections=[
        ("1. Ads: are you paying for the wrong searches?",
         [f"Customers search things like {t['searches']}. Ads are also shown for searches from people who will never call, such as {t['waste']}.",
          "Today: in Google Ads open Insights and reports, then Search terms. Look at the last 30 days sorted by cost and add the clear 'no' searches as negative keywords."], []),
        ("2. Your Google Business Profile", [t["maps"], "Today: check phone, hours and categories are correct and add three recent photos."], []),
        ("3. Reviews", [t["review"], "Today: reply to every review that has no reply. Future customers read the replies as well."], []),
        ("4. Your website", [t["page"], "Today: test it on your own phone. If it is slow, visitors go to the next business. Our free check at kerdos.sgdventures.com/check.html measures it in 30 seconds."], []),
      ],
      faq=[("How much can this save?","It depends on your account. Checking your own search terms shows the real figure, so we do not quote one in advance."),
           ("Do you need access to my accounts?","For the free report, no. If you later subscribe, access is by invitation only and we never ask for passwords.")])
